# Resolved from this file rather than from $HOME: the icons sit beside the code in the
# same tree, so this is right whichever user owns the device and also when the app is
# started from a staging copy during an update.
ICONS_DIR = os.path.join(
    os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))),
    "config", "icons")


def app_icon():
    """The window icon, assembled from every size that ships in config/icons/."""
    icon = QIcon()
    for size in (16, 32, 48, 64, 128, 256):
        path = os.path.join(ICONS_DIR, "athan-app-icon-%d.png" % size)
        if os.path.exists(path):
            icon.addFile(path)
    return icon

# The version this device is actually running, which is not a property of this file.
# check_updates.sh writes var/installed_version after a release passes its health check,
# so that file - not a constant baked into the payload - is the only honest answer. A
# constant here would still read "1.0.0" on a device that has taken four updates.
INSTALLED_VERSION_FILE = os.path.join(
    os.path.expanduser("~"), "Desktop", "scheduler", "var", "installed_version"
)


def installed_version():
    """Read on every refresh, never cached.

    check_updates.sh relaunches this app *before* it runs the health check, and writes
    var/installed_version only *after* the check passes. A value read once at startup
    would therefore show the previous version for the whole life of the process - which
    is exactly the moment someone looks at this label to see whether an update landed.
    """
    try:
        with open(INSTALLED_VERSION_FILE, encoding="utf-8") as handle:
            version = handle.read().strip()
    except OSError:
        return "—"
    return version if version and version != "unknown" else "—"

# =============================================================================
# APPEARANCE
# -----------------------------------------------------------------------------
# Every size, font, ratio and margin the countdown page is built from. Change a
# value here and the layout follows; nothing below hard-codes these numbers.
#
# Sizes are ratios of the window, not fixed points, and are measured against the
# font at runtime - a fixed point size is only ever correct for the one font it
# was chosen against, and this app resolves different fonts on different devices.
# Ratios are of the window's own width/height, so 0.5 is half the screen.
# =============================================================================

# --- Fonts -------------------------------------------------------------------
# Two families, by role. The Arabic label uses Amiri, the typeface this project
# ships and installs (config/fonts/arabic-fonts) and which the settings app and
# the daily table already use. Amiri's numerals are old-style and finely stroked;
# the digits keep the grotesque face the counter has always had, which reads far
# better across a room.
COUNTDOWN_NAME_FONT = "Amiri"
COUNTDOWN_DIGITS_FONT = "DejaVu Sans"
# Speaker glyphs live in Noto Sans Symbols2, which init.sh installs - DejaVu Sans
# does not carry them. A device that has not been re-initialised draws a box here.
SYMBOL_FONT = "Noto Sans Symbols2"
SPEAKER_ON = "\U0001F50A"
SPEAKER_OFF = "\U0001F507"

# --- Prayer name -------------------------------------------------------------
# Ink, not line box: Amiri reserves half again its drawn height for diacritics
# these labels never use, so sizing by QFontMetrics.height() would draw it far
# smaller than a font whose box is tight. Measuring what is actually painted
# keeps the name the same size on screen whichever family the device resolves.
COUNTDOWN_NAME_INK_RATIO = 0.265      # ink height, as a share of window height
COUNTDOWN_NAME_WIDTH_RATIO = 0.65     # ink width, as a share of window width
COUNTDOWN_NAME_INK_TOP_RATIO = 0.165  # where the ink starts, from the window top
COUNTDOWN_NAME_MAX_PT = 130           # search bounds for the fitted size
COUNTDOWN_NAME_MIN_PT = 30

# --- Countdown digits --------------------------------------------------------
COUNTDOWN_DIGITS_INK_RATIO = 0.35     # ink height, as a share of window height
COUNTDOWN_DIGITS_WIDTH_RATIO = 0.85   # ink width, as a share of window width
COUNTDOWN_DIGITS_MAX_PT = 300         # search bounds for the fitted size
COUNTDOWN_DIGITS_MIN_PT = 80
# The digits are drawn through a graphics view so they can be stretched taller
# than the font draws them, which is the look this counter has always had.
COUNTDOWN_DIGITS_STRETCH_Y = 1.35
# Nudges the digits within the height left to them. Zero because frame_digits
# hands the view the painted band instead of the whole line box, which centres
# them on its own; kept as the knob to lean on if a future font needs the help.
COUNTDOWN_SHIFT_Y = 0

# --- Margins -----------------------------------------------------------------
# The digits start at a fixed height whatever the name does, because the name is
# placed rather than laid out. Growing the name cannot push the digits down: it
# keeps its ink top and grows into the gap between the two.
COUNTDOWN_VIEW_TOP_RATIO = 0.429      # where the digits' area starts
COUNTDOWN_SIDE_MARGIN = 9
COUNTDOWN_BOTTOM_MARGIN = 9

# --- Makrooh notice ----------------------------------------------------------
# Placed on the page rather than in the layout, in the strip beside the window
# buttons. In the layout it would push the name and digits down whenever it
# appeared; out of the flow, showing or hiding it moves nothing. Capped so every
# notice renders at much the same height whatever its text.
COUNTDOWN_NOTICE_TOP = 6
COUNTDOWN_NOTICE_HEIGHT = 50
COUNTDOWN_NOTICE_MAX_PT = 22
COUNTDOWN_NOTICE_MIN_PT = 14

# --- Countdown page backgrounds ----------------------------------------------
# Deeper shades than the daily table's PERIOD_COLORS, which are read on a card
# rather than across a room. Makrooh is the exception: one orange, shared with
# the table, so both screens agree on what a makrooh window looks like.
COUNTDOWN_BG_DEFAULT = "#333333"
COUNTDOWN_BG_GREEN = "#006600"    # the 20 minutes after an athan
COUNTDOWN_BG_RED = "#990000"      # the 20 minutes before the next athan
# Both makrooh windows: from sunrise until Duha opens, and the zawal stretch at
# the end of Duha. Neither is merely "the next athan is close" - praying nafl in
# them is discouraged, so they read as their own state rather than as red.
# The deep burnt orange this counter has always used. A lighter, brighter orange
# washes out to yellow on these panels and leaves white text hard to read on it.
COUNTDOWN_BG_MAKROOH = "#BF360C"

# --- Window buttons ----------------------------------------------------------
# A row of four in the top-left corner: close, fullscreen, view, mute. Centred
# text on the notice line is shrunk until it clears them.
WINDOW_BUTTON_LEFT = 10               # x of the first button
WINDOW_BUTTON_PITCH = 48              # x step between buttons
WINDOW_BUTTON_WIDTH = 48
WINDOW_BUTTON_HEIGHT = 50
WINDOW_BUTTON_FONT_PX = 20
WINDOW_BUTTONS_RIGHT_EDGE = 210       # what the notice has to stay clear of
# Each glyph sits at a different height inside its own line box, so the four are
# nudged individually to put their ink on one line. Measured, not guessed: the
# centres were 35.5 / 35.0 / 37.5 / 36.0 before these offsets.
EXIT_ICON_Y = 10           # ✖
FULLSCREEN_ICON_Y = 11     # ⛶
# The view button swaps its glyph per page and the two sit at different heights.
VIEW_ICON_Y_COUNTER = 11   # ☰
VIEW_ICON_Y_DAILY = 8      # ◷
# The speaker glyphs draw larger and higher than the rest at a shared size, so
# they carry their own size and drop.
MUTE_ICON_Y = 14
MUTE_ICON_SIZE = 16
# The muted glyph is a ring around mostly empty space, so at the size that
# matches the others by ink box it reads lighter. It is drawn larger to make up.
MUTE_ICON_SIZE_MUTED = 20
MUTED_COLOR = "#dc3545"


# The scheduler service and this GUI run as the same desktop user, so a plain file under
# var/ is all that is needed to pass the mute state between them - no restart, no sudo.
SCHEDULER_DIR = os.path.join(os.path.expanduser("~"), "Desktop", "scheduler")
MUTE_FLAG_FILE = os.path.join(SCHEDULER_DIR, "var", "mute.flag")
PLAYER_SCRIPT_FILE = os.path.join(SCHEDULER_DIR, "config", "scripts", "play_audio.sh")
# Muting is temporary: the flag holds the epoch second the mute lapses, so the scheduler
# and the player can each honour the expiry on their own. Keeping the deadline in the
# file rather than in this process means a mute still lifts if the GUI is closed or
# restarted while it is active - otherwise the athan could stay off with no way back.
MUTE_DURATION_MINUTES = 60

# Muting acts on the output device, not on the player: an athan already playing goes
# silent at once and comes back mid-stream when unmuted. Killing the player silences it
# just as fast, but nothing can bring it back - so that is only the fallback, for a
# device where the device cannot be reached.
#
# wpctl ships with wireplumber, the session manager already running here. pactl is not
# installed on the device and amixer finds no usable Master control on this hardware.
AUDIO_SINK = "@DEFAULT_AUDIO_SINK@"
AUDIO_MUTE_CMD = ["wpctl", "set-mute", AUDIO_SINK]
AUDIO_STATE_CMD = ["wpctl", "get-volume", AUDIO_SINK]
AUDIO_CMD_TIMEOUT = 3
# The device is asked how it stands rather than trusted to still be as it was left, so
# the button cannot claim sound is on while the speaker is silent. Every second would
# fork a process a second for the life of the kiosk; two is far below noticing.
AUDIO_STATE_POLL_SECONDS = 2


def window_button_box(index, icon_y):
    """Geometry of the nth window button. Each glyph carries its own y so their ink
    lands on one line despite sitting differently inside their line boxes."""
    return (WINDOW_BUTTON_LEFT + index * WINDOW_BUTTON_PITCH, icon_y,
            WINDOW_BUTTON_WIDTH, WINDOW_BUTTON_HEIGHT)


def audio_set_mute(muted):
    """Silence or restore the output device. False if the device could not be reached."""
    try:
        subprocess.run(AUDIO_MUTE_CMD + ["1" if muted else "0"], check=True,
                       capture_output=True, timeout=AUDIO_CMD_TIMEOUT)
        return True
    except (OSError, subprocess.SubprocessError):
        return False


def audio_is_muted():
    """Whether the output device is silenced, or None if it cannot be asked."""
    try:
        state = subprocess.run(AUDIO_STATE_CMD, check=True, capture_output=True,
                               text=True, timeout=AUDIO_CMD_TIMEOUT).stdout
    except (OSError, subprocess.SubprocessError):
        return None
    return "[MUTED]" in state


def mute_expiry():
    """Epoch second this mute ends, or None if there is no readable mute in force."""
    try:
        with open(MUTE_FLAG_FILE) as flag:
            return int(flag.read().strip())
    except (OSError, ValueError):
        return None


def is_muted():
    expiry = mute_expiry()
    return expiry is not None and datetime.now().timestamp() < expiry


# -------------------------
# Build date → prayer map
# -------------------------
# Rebuilt in place rather than rebound, so every reference held elsewhere sees the new
# times: apply_settings.sh rewrites prayer_times_map.py underneath a running app - from
# the Settings GUI and from the new year's cron job - and it restarts the athan service
# but not this one. Without a reload the screen would keep showing the times it was
# started with, for as long as the kiosk stays up.
prayersByDate = {}
PRAYER_MAP_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "prayer_times_map.py")
_prayer_map_mtime = None


def load_prayer_times():
    """Re-read the generated map. False if it could not be read this time.

    Read and executed rather than imported: import would answer from the .pyc cache,
    which is judged stale only by the source's size and mtime in whole seconds. Every
    time is HH:MM, so a regenerated map is very often exactly the same size as the one
    before it, and a changed prayer time would be silently ignored. The athan service
    reads the same file the same way."""
    global _prayer_map_mtime
    namespace = {}
    try:
        stamp = os.path.getmtime(PRAYER_MAP_FILE)
        with open(PRAYER_MAP_FILE, encoding="utf-8") as handle:
            exec(handle.read(), {}, namespace)
        rows = namespace["prayerTimes"]
    except (OSError, SyntaxError, ValueError, KeyError):
        # cp -f is not atomic, so a read can land mid-write. The old times stay in
        # place and the mtime is left unrecorded, which retries on the next tick.
        return False

    prayersByDate.clear()
    for pt in rows:
        prayersByDate[f"{pt['Month']}-{pt['Day']}"] = {
            "الفجر": pt.get("Fajr"),
            "الشروق": pt.get("Sunrise"),
            "الظهر": pt.get("Dhuhr"),
            "العصر": pt.get("Asr"),
            "المغرب": pt.get("Maghrib"),
            "العشاء": pt.get("Isha"),
        }
    _prayer_map_mtime = stamp
    return True


def prayer_times_changed():
    """True when the generated map has been rewritten since it was last read."""
    try:
        return os.path.getmtime(PRAYER_MAP_FILE) != _prayer_map_mtime
    except OSError:
        return False


load_prayer_times()

prayerOrder = ["الفجر", "الشروق", "الظهر", "العصر", "المغرب", "العشاء"]




_prayer_font_cache = {}
_countdown_font_cache = {}


def _countdown_labels():
    return [prayer_display_name(name) for name in dailyPrayerOrder]


def fit_prayer_font(available_width, available_height):
    """One size for every prayer, chosen so the longest name still fits.

    Sized from the longest label rather than the one on screen: width-fitting each name
    on its own would draw الشروق far larger than صلاة المغرب, and the text would change
    size through the day. Both axes are bounded as a fraction of the window and measured
    from the painted ink, so the name comes out the same size whatever family the device
    resolves - the app ships Amiri, but a machine without it falls back to something with
    quite different metrics.
    """
    key = (available_width, available_height)
    if key in _prayer_font_cache:
        return _prayer_font_cache[key]

    labels = _countdown_labels()
    max_width = available_width * COUNTDOWN_NAME_WIDTH_RATIO
    max_ink = available_height * COUNTDOWN_NAME_INK_RATIO

    chosen = QFont(COUNTDOWN_NAME_FONT, COUNTDOWN_NAME_MIN_PT, QFont.Bold)
    for size in range(COUNTDOWN_NAME_MAX_PT, COUNTDOWN_NAME_MIN_PT - 1, -1):
        metrics = QFontMetrics(QFont(COUNTDOWN_NAME_FONT, size, QFont.Bold))
        rects = [metrics.tightBoundingRect(t) for t in labels]
        if (max(r.height() for r in rects) <= max_ink
                and max(r.width() for r in rects) <= max_width):
            chosen = QFont(COUNTDOWN_NAME_FONT, size, QFont.Bold)
            break

    _prayer_font_cache[key] = chosen
    return chosen


def prayer_name_top_margin(font, available_height):
    """Top margin that puts the name's ink at the same height for any font.

    A font with a deep ascent starts painting lower inside its own line box, so a fixed
    margin drops the name further down the screen for some families than others. The
    ascent is subtracted back out here."""
    metrics = QFontMetrics(font)
    ink_offset = metrics.ascent() + min(
        metrics.tightBoundingRect(t).top() for t in _countdown_labels())
    return max(0, round(available_height * COUNTDOWN_NAME_INK_TOP_RATIO) - ink_offset)


def fit_countdown_font(available_width, available_height):
    """Largest digits whose ink fits the height left under the name, measured the same
    way as the name so the two keep their proportion across fonts."""
    key = (available_width, available_height)
    if key in _countdown_font_cache:
        return _countdown_font_cache[key]

    max_ink = available_height * COUNTDOWN_DIGITS_INK_RATIO
    max_width = available_width * COUNTDOWN_DIGITS_WIDTH_RATIO

    chosen = QFont(COUNTDOWN_DIGITS_FONT, COUNTDOWN_DIGITS_MIN_PT, QFont.Bold)
    for size in range(COUNTDOWN_DIGITS_MAX_PT, COUNTDOWN_DIGITS_MIN_PT - 1, -1):
        font = QFont(COUNTDOWN_DIGITS_FONT, size, QFont.Bold)
        rect = QFontMetrics(font).tightBoundingRect("00:00")
        if rect.height() <= max_ink and rect.width() <= max_width:
            chosen = font
            break

    _countdown_font_cache[key] = chosen
    return chosen


def fit_notice_font(text, available_width):
    """Largest size whose centred text starts to the right of the window buttons."""
    for size in range(COUNTDOWN_NOTICE_MAX_PT, COUNTDOWN_NOTICE_MIN_PT - 1, -1):
        font = QFont(COUNTDOWN_NAME_FONT, size, QFont.Bold)
        width = QFontMetrics(font).horizontalAdvance(text)
        if (available_width - width) / 2 >= WINDOW_BUTTONS_RIGHT_EDGE:
            return font
    return QFont(COUNTDOWN_NAME_FONT, COUNTDOWN_NOTICE_MIN_PT, QFont.Bold)


def duha_window(now):
    """The stretch from الشروق to الظهر, which this page models as الضحى's own period
    rather than as a plain countdown to the الظهر athan.

    Returns (duha_start, dhuhr) while inside it, otherwise None.
    """
    times = prayersByDate.get(key_for_date(now), {})
    sunrise_str, dhuhr_str = times.get("الشروق"), times.get("الظهر")
    if not sunrise_str or not dhuhr_str:
        return None
    sunrise_dt = build_datetime(now, sunrise_str)
    dhuhr_dt = build_datetime(now, dhuhr_str)
    if not sunrise_dt <= now < dhuhr_dt:
        return None
    return sunrise_dt + timedelta(minutes=DUHA_AFTER_SUNRISE_MINUTES), dhuhr_dt


def prayer_display_name(name):
    """الشروق is neither a صلاة nor has an أذان, so it is the one entry shown bare."""
    return name if name == "الشروق" else f"صلاة {name}"


def key_for_date(d):
    return f"{d.month}-{d.day}"

def build_datetime(date, time_str):
    if not time_str:
        return None
    h, m = map(int, time_str.split(":"))
    return datetime(date.year, date.month, date.day, h, m)

def next_occurrence(prayer, now):
    today_time = prayersByDate.get(key_for_date(now), {}).get(prayer)
    if today_time:
        dt = build_datetime(now, today_time)
        if dt > now:
            return dt
    tomorrow = now + timedelta(days=1)
    tomorrow_time = prayersByDate.get(key_for_date(tomorrow), {}).get(prayer)
    if tomorrow_time:
        return build_datetime(tomorrow, tomorrow_time)
    return None

def prev_occurrence(prayer, now):
    today_time = prayersByDate.get(key_for_date(now), {}).get(prayer)
    if today_time:
        dt = build_datetime(now, today_time)
        if dt <= now:
            return dt
    yesterday = now - timedelta(days=1)
    y_time = prayersByDate.get(key_for_date(yesterday), {}).get(prayer)
    if y_time:
        return build_datetime(yesterday, y_time)
    return None

def get_prev_next_prayer(now):
    prev_p = next_p = None
    prev_t = next_t = None
    for p in prayerOrder:
        nt = next_occurrence(p, now)
        pt = prev_occurrence(p, now)
        if nt and (not next_t or nt < next_t):
            next_p, next_t = p, nt
        if pt and (not prev_t or pt > prev_t):
            prev_p, prev_t = p, pt
    return prev_p, next_p, prev_t, next_t


# -------------------------
# Daily prayer table
# -------------------------
DUHA_AFTER_SUNRISE_MINUTES = 20
# The countdown page is the reference: green for the 20 minutes after an athan, red for
# the 20 minutes before the next one.
PERIOD_EDGE_MINUTES = 20
# A date picked by hand is a temporary detour on a kiosk that nobody signs out of, so
# the table drops back to today once it has been left alone this long.
BROWSE_RESET_MINUTES = 10

# The weekday names read in Arabic; the months and years stay numbers, which need no
# translating and keep the bar narrow. Weekday names are the same in every Arabic locale,
# so the calendar takes ar_MA purely for its Western day numerals - ar_SY and its
# neighbours number the grid in Arabic-Indic digits, which would be the only place in
# the whole app to use them.
CALENDAR_LOCALE = QLocale(QLocale.Arabic, QLocale.Morocco)
# The year list opens on the current year with three either side in view, and scrolls
# from there - far easier on a touchscreen than the spin box Qt gives by default.
CALENDAR_YEARS_VISIBLE = 7
CALENDAR_YEAR_SPAN = 10

dailyPrayerOrder = ["الفجر", "الشروق", "الضحى", "الظهر", "العصر", "المغرب", "العشاء"]

MAKROOH_LABEL = "مكروه"

PERIOD_COLORS = {
    "green": "#198754",
    "beige": "#E7DBC1",
    "red": "#dc3545",
    "makrooh": COUNTDOWN_BG_MAKROOH,
}

PERIOD_TEXT = {
    "green": "#FFFFFF",
    "beige": "#4A3F2F",
    "red": "#FFFFFF",
    "makrooh": "#FFFFFF",
}

PAGE_BG = "#0F172A"
PAGE_GRADIENT = ("qlineargradient(x1:0, y1:0, x2:0, y2:1,"
                 " stop:0 #0F172A, stop:1 #1B2437)")
PAGE_TEXT = "#F8FAFC"
CARD_BG = "#1E293B"
CARD_BORDER = "#475569"
INPUT_BORDER = "#475569"
NAME_COLOR = "#F1F5F9"
TIME_COLOR = "#F1F5F9"
FOOTER_COLOR = "#64748B"


def daily_times(view_date):
    times = prayersByDate.get(key_for_date(view_date))
    if not times:
        return None
    resolved = {}
    for name in dailyPrayerOrder:
        if name == "الضحى":
            sunrise = resolved.get("الشروق")
            resolved[name] = (sunrise + timedelta(minutes=DUHA_AFTER_SUNRISE_MINUTES)
                              if sunrise else None)
        else:
            resolved[name] = build_datetime(view_date, times.get(name))
    return resolved


def daily_rows(view_date, now, is_today):
    """One entry per prayer: the time shown on the card, plus the period it opens.

    A prayer's period runs until the next prayer starts, so the running period is the
    one the current time falls into - that is the row the page highlights."""
    times = daily_times(view_date)
    if not times:
        return None

    rows = []
    for index, name in enumerate(dailyPrayerOrder):
        if index + 1 < len(dailyPrayerOrder):
            end = times[dailyPrayerOrder[index + 1]]
        else:
            next_day = daily_times(view_date + timedelta(days=1))
            end = next_day["الفجر"] if next_day else None
        rows.append({"name": name, "time": times[name], "start": times[name], "end": end})

    # Isha is the only period that crosses midnight, so between midnight and Fajr the
    # running period is yesterday evening's. The card keeps showing tonight's Isha.
    fajr = times["الفجر"]
    if is_today and fajr and now < fajr:
        yesterday = daily_times(view_date - timedelta(days=1))
        if yesterday and yesterday["العشاء"]:
            rows[-1]["start"] = yesterday["العشاء"]
            rows[-1]["end"] = fajr

    return rows


def period_state(name, start, end, now):
    """Colour of the running period, and whether praying nafl in it is makrooh.

    The two makrooh windows are the ones the countdown page already warns about: from
    sunrise until Duha opens, and the zawal stretch just before Dhuhr. The red state on
    every other period only means the next athan is close - it is not makrooh."""
    duration = int((end - start).total_seconds() // 60)
    remaining = int((end - now).total_seconds() // 60)
    if name == "الشروق":
        return "makrooh", True
    # Zawal, the close of Duha. Makrooh in its own right, so it takes the makrooh
    # colour rather than the red that only means the next athan is near - the same
    # sense the countdown page uses for this window.
    if name == "الضحى" and remaining <= PERIOD_EDGE_MINUTES:
        return "makrooh", True
    if duration - PERIOD_EDGE_MINUTES < remaining:
        return "green", False
    if remaining <= PERIOD_EDGE_MINUTES:
        return "red", False
    return "beige", False


# -------------------------
# Date picker
# -------------------------
class DatePickerDialog(QDialog):
    def __init__(self, current, parent=None):
        super().__init__(parent)
        # The window manager decorations are useless on a frameless kiosk, and their
        # buttons are too small to hit on the touchscreen anyway.
        self.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint)
        self.setLayoutDirection(Qt.RightToLeft)
        self.setStyleSheet(f"QDialog {{ background-color: {PAGE_BG};"
                           f" border: 2px solid {INPUT_BORDER}; }}")
        self.selected_date = None

        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        title = QLabel("اختر التاريخ")
        title.setAlignment(Qt.AlignCenter)
        title.setFont(QFont("Amiri", 17))
        title.setStyleSheet(f"color: {PAGE_TEXT};")
        layout.addWidget(title)

        self.calendar = QCalendarWidget()
        # Gregorian dates read left to right, like the date button they came from
        self.calendar.setLayoutDirection(Qt.LeftToRight)
        self.calendar.setLocale(CALENDAR_LOCALE)
        # Qt's own bar offers the year through a spin box, which is a poor target on a
        # touchscreen and shows one year at a time. Replaced below by two dropdowns.
        self.calendar.setNavigationBarVisible(False)
        self.calendar.setGridVisible(True)
        self.calendar.setVerticalHeaderFormat(QCalendarWidget.NoVerticalHeader)
        self.calendar.setHorizontalHeaderFormat(QCalendarWidget.ShortDayNames)
        self.calendar.setSelectedDate(QDate(current.year, current.month, current.day))
        self.calendar.setStyleSheet(
            f"QCalendarWidget QWidget#qt_calendar_navigationbar {{"
            f" background-color: {CARD_BG}; }}"
            f"QCalendarWidget QToolButton {{ height: 34px; font-size: 15px;"
            f" color: {NAME_COLOR}; background-color: transparent; border: none; }}"
            f"QCalendarWidget QMenu, QCalendarWidget QSpinBox {{"
            f" background-color: {CARD_BG}; color: {NAME_COLOR}; }}"
            f"QCalendarWidget QAbstractItemView:enabled {{ font-size: 15px;"
            f" color: {NAME_COLOR}; background-color: {PAGE_BG};"
            f" gridline-color: {CARD_BORDER};"
            f" selection-background-color: {PERIOD_COLORS['makrooh']};"
            " selection-color: #FFFFFF; }"
            "QCalendarWidget QAbstractItemView:disabled { color: #64748B; }"
        )
        self.nav_style = (
            f"QComboBox {{ height: 38px; font-size: 16px; padding: 0 8px;"
            f" color: {PAGE_TEXT}; background-color: {CARD_BG};"
            f" border: 2px solid {INPUT_BORDER}; border-radius: 6px; }}"
            f"QComboBox QAbstractItemView {{ font-size: 16px;"
            f" color: {PAGE_TEXT}; background-color: {CARD_BG};"
            f" selection-background-color: {PERIOD_COLORS['makrooh']};"
            " selection-color: #FFFFFF; outline: none; }"
            f"QPushButton {{ min-width: 44px; height: 38px; font-size: 20px;"
            f" color: {PAGE_TEXT}; background-color: {CARD_BG};"
            f" border: 2px solid {INPUT_BORDER}; border-radius: 6px; }}"
        )
        # The weekday header is painted from these formats, not from the stylesheet
        header_format = QTextCharFormat()
        header_format.setForeground(QBrush(QColor(NAME_COLOR)))
        header_format.setBackground(QBrush(QColor(CARD_BG)))
        self.calendar.setHeaderTextFormat(header_format)
        for weekday in (Qt.Saturday, Qt.Sunday):
            weekend_format = QTextCharFormat()
            weekend_format.setForeground(QBrush(QColor(NAME_COLOR)))
            self.calendar.setWeekdayTextFormat(weekday, weekend_format)
        self.calendar.clicked.connect(self.pick_date)

        # Its table asks for cells far wider than this screen, which clips every column
        # past the first two - stretch the cells into the room the dialog actually has.
        table = self.calendar.findChild(QTableView, "qt_calendar_calendarview")
        if table is not None:
            table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
            table.verticalHeader().setSectionResizeMode(QHeaderView.Stretch)
        layout.addWidget(self.build_nav_bar())
        layout.addWidget(self.calendar)

        cancel_btn = QPushButton("إلغاء")
        cancel_btn.setFont(QFont("Amiri", 16))
        cancel_btn.setMinimumHeight(44)
        cancel_btn.setStyleSheet(
            f"QPushButton {{ background: {CARD_BG}; color: {PAGE_TEXT};"
            f" border: 2px solid {INPUT_BORDER}; border-radius: 6px; }}"
        )
        cancel_btn.clicked.connect(self.reject)
        layout.addWidget(cancel_btn)

        self.setFixedSize(*self.dialog_size())

    def build_nav_bar(self):
        """Month and year as dropdowns, with an arrow either side for the next month.

        Carried on its own widget so it can be left to right like the grid below it,
        which stays Gregorian - in the dialog's own right-to-left flow the back arrow
        would sit on the right, pointing the opposite way to the month it moves."""
        bar = QWidget()
        bar.setLayoutDirection(Qt.LeftToRight)
        row = QHBoxLayout(bar)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(6)

        prev_btn = QPushButton("‹")
        next_btn = QPushButton("›")
        prev_btn.clicked.connect(self.calendar.showPreviousMonth)
        next_btn.clicked.connect(self.calendar.showNextMonth)

        self.month_box = QComboBox()
        for month in range(1, 13):
            self.month_box.addItem(f"{month:02d}", month)
        self.year_box = QComboBox()
        self.year_box.setMaxVisibleItems(CALENDAR_YEARS_VISIBLE)

        for widget in (prev_btn, next_btn, self.month_box, self.year_box):
            widget.setStyleSheet(self.nav_style)

        shown = self.calendar.selectedDate()
        self.fill_years(shown.year())
        self.show_page(shown.year(), shown.month())

        self.month_box.activated.connect(self.nav_changed)
        self.year_box.activated.connect(self.nav_changed)
        # Keeps the dropdowns honest when the arrows move the page instead.
        self.calendar.currentPageChanged.connect(self.show_page)

        row.addWidget(prev_btn)
        row.addWidget(self.month_box, 1)
        row.addWidget(self.year_box, 1)
        row.addWidget(next_btn)
        return bar

    def fill_years(self, around):
        """A span of years centred on the one in view, so the list scrolls both ways."""
        self.year_box.blockSignals(True)
        self.year_box.clear()
        for year in range(around - CALENDAR_YEAR_SPAN, around + CALENDAR_YEAR_SPAN + 1):
            self.year_box.addItem(str(year), year)
        self.year_box.blockSignals(False)

    def show_page(self, year, month):
        """Point the dropdowns at the month on display, without steering it back."""
        if self.year_box.findData(year) < 0:
            # Arrowed past the end of the list - recentre it rather than lose the year.
            self.fill_years(year)
        for box, value in ((self.month_box, month), (self.year_box, year)):
            box.blockSignals(True)
            box.setCurrentIndex(box.findData(value))
            box.blockSignals(False)

    def nav_changed(self, _index):
        self.calendar.setCurrentPage(self.year_box.currentData(),
                                     self.month_box.currentData())

    def dialog_size(self):
        """Fit the screen the app is actually on, rather than a guessed minimum."""
        parent = self.parentWidget()
        if parent is not None and parent.width() > 100 and parent.height() > 100:
            available = parent.size()
        else:
            available = QApplication.primaryScreen().availableGeometry().size()
        return int(available.width() * 0.92), int(available.height() * 0.92)

    def showEvent(self, event):
        super().showEvent(event)
        parent = self.parentWidget()
        if parent is not None:
            center = parent.mapToGlobal(parent.rect().center())
            self.move(center.x() - self.width() // 2, center.y() - self.height() // 2)

    def pick_date(self, qdate):
        self.selected_date = date_cls(qdate.year(), qdate.month(), qdate.day())
        self.accept()


