class PrayerCard(QWidget):
    IDLE_HEIGHT = 42
    ACTIVE_HEIGHT = 52

    def __init__(self, name):
        super().__init__()
        self.setObjectName("prayerCard")
        # Plain QWidgets ignore a stylesheet background unless they are told to paint one
        self.setAttribute(Qt.WA_StyledBackground, True)
        self.setLayoutDirection(Qt.LeftToRight)
        self.setFixedHeight(self.IDLE_HEIGHT)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(14, 4, 14, 4)

        self.time_label = QLabel("--:--")
        self.time_label.setObjectName("prayerTime")

        self.makrooh_label = QLabel(MAKROOH_LABEL)
        self.makrooh_label.setObjectName("makroohTag")
        self.makrooh_label.hide()

        self.name_label = QLabel(name)
        self.name_label.setObjectName("prayerName")

        layout.addWidget(self.time_label)
        layout.addSpacing(10)
        layout.addWidget(self.makrooh_label)
        layout.addStretch()
        layout.addWidget(self.name_label)

        # Lifts the running prayer off the page instead of only recolouring it
        self.shadow = QGraphicsDropShadowEffect(self)
        self.shadow.setBlurRadius(16)
        self.shadow.setOffset(0, 0)
        self.shadow.setColor(QColor(0, 0, 0, 120))
        self.shadow.setEnabled(False)
        self.setGraphicsEffect(self.shadow)

        self.state = None
        self.apply_state("--:--", None)

    def apply_state(self, time_text, color, makrooh=False):
        self.time_label.setText(time_text)
        self.makrooh_label.setVisible(makrooh)

        # Restyling on every tick would repaint the whole list once a second
        state = (color, makrooh)
        if state == self.state:
            return
        self.state = state

        active = color is not None
        if active:
            base = QColor(PERIOD_COLORS[color])
            light_fill = base.lightness() > 170
            background = ("qlineargradient(x1:0, y1:0, x2:1, y2:0,"
                          f" stop:0 {base.name()},"
                          f" stop:1 {base.darker(112 if light_fill else 128).name()})")
            border = base.darker(112).name() if light_fill else base.lighter(118).name()
            name_color = time_color = PERIOD_TEXT[color]
            glow = QColor(base); glow.setAlpha(90)
            self.shadow.setColor(glow)
        else:
            background = CARD_BG
            border = CARD_BORDER
            name_color = NAME_COLOR
            time_color = TIME_COLOR

        self.setFixedHeight(self.ACTIVE_HEIGHT if active else self.IDLE_HEIGHT)
        weight = QFont.Bold if active else QFont.DemiBold
        self.time_label.setFont(QFont("DejaVu Sans Mono", 17 if active else 15, weight))
        self.makrooh_label.setFont(QFont("Amiri", 16, weight))
        self.name_label.setFont(QFont("Amiri", 22 if active else 19, weight))
        self.shadow.setEnabled(active)

        self.setStyleSheet(
            f"#prayerCard {{ background: {background};"
            f" border: 2px solid {border}; border-radius: 12px; }}"
            f"#prayerCard QLabel {{ background: transparent; border: none; }}"
            f"#prayerCard #prayerName {{ color: {name_color}; }}"
            f"#prayerCard #prayerTime {{ color: {time_color}; letter-spacing: 1px; }}"
            f"#prayerCard #makroohTag {{ color: {name_color}; }}"
        )


class DailyPrayersPage(QWidget):
    def __init__(self):
        super().__init__()
        self.setObjectName("dailyPage")
        self.setAttribute(Qt.WA_StyledBackground, True)
        self.setLayoutDirection(Qt.RightToLeft)
        self.setStyleSheet(f"#dailyPage {{ background: {PAGE_GRADIENT}; }}")

        self.view_date = date_cls.today()
        # The date the calendar last read as "today", used to tell a view that is
        # tracking today from one the user pinned deliberately.
        self.last_today = self.view_date
        # When a hand-picked date was chosen, or None while the view follows today.
        self.browsed_at = None

        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 4, 0, 4)
        outer.setAlignment(Qt.AlignCenter)

        container = QWidget()
        # Wider than the phone-shaped web layout: on an 800x480 panel read from a
        # distance, the extra width buys legibility that portrait proportions do not.
        container.setFixedWidth(520)
        layout = QVBoxLayout(container)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(5)

        # Date row: the date itself is the button, with a calendar button beside it
        date_row = QWidget()
        date_row.setLayoutDirection(Qt.LeftToRight)
        date_layout = QHBoxLayout(date_row)
        date_layout.setContentsMargins(0, 0, 0, 0)
        date_layout.setSpacing(0)

        self.date_btn = QPushButton()
        self.date_btn.setFont(QFont("DejaVu Sans", 15))
        self.date_btn.setMinimumHeight(40)
        self.date_btn.setMinimumWidth(180)
        self.date_btn.setStyleSheet(
            f"QPushButton {{ background: {CARD_BG}; color: {PAGE_TEXT};"
            f" border: 2px solid {INPUT_BORDER}; border-right: none;"
            " border-top-left-radius: 10px; border-bottom-left-radius: 10px; }"
        )
        self.date_btn.clicked.connect(self.open_date_picker)

        self.calendar_btn = QPushButton("▦")
        self.calendar_btn.setFont(QFont("DejaVu Sans", 15))
        self.calendar_btn.setMinimumHeight(40)
        self.calendar_btn.setFixedWidth(52)
        self.calendar_btn.setStyleSheet(
            f"QPushButton {{ background: {CARD_BG}; color: {PAGE_TEXT};"
            f" border: 2px solid {INPUT_BORDER};"
            " border-top-right-radius: 10px; border-bottom-right-radius: 10px; }"
        )
        self.calendar_btn.clicked.connect(self.open_date_picker)

        date_layout.addStretch()
        date_layout.addWidget(self.date_btn)
        date_layout.addWidget(self.calendar_btn)
        date_layout.addStretch()
        layout.addWidget(date_row)

        self.today_btn = QPushButton("اليوم")
        self.today_btn.setFont(QFont("Amiri", 14))
        self.today_btn.setMinimumHeight(30)
        self.today_btn.setStyleSheet(
            "QPushButton { background: transparent; color: #60A5FA;"
            " border: 2px solid #60A5FA; border-radius: 6px; padding: 2px 10px; }"
        )
        self.today_btn.clicked.connect(self.go_today)
        today_row = QHBoxLayout()
        today_row.addStretch()
        today_row.addWidget(self.today_btn)
        today_row.addStretch()
        layout.addLayout(today_row)

        self.badge = QLabel("--:--")
        self.badge.setAlignment(Qt.AlignCenter)
        self.badge.setFont(QFont("DejaVu Sans Mono", 17, QFont.Bold))
        self.badge.setMinimumHeight(38)
        self.badge.setFixedWidth(130)
        self.badge_glow = QGraphicsDropShadowEffect(self.badge)
        self.badge_glow.setBlurRadius(26)
        self.badge_glow.setOffset(0, 0)
        self.badge.setGraphicsEffect(self.badge_glow)
        badge_row = QHBoxLayout()
        badge_row.addStretch()
        badge_row.addWidget(self.badge)
        badge_row.addStretch()
        layout.addLayout(badge_row)

        # Own layout so the gap between cards can be wider than the gap between the
        # header rows, and so the active card's glow has room instead of being clipped
        cards_layout = QVBoxLayout()
        cards_layout.setContentsMargins(14, 2, 14, 2)
        cards_layout.setSpacing(7)
        self.cards = {}
        for name in dailyPrayerOrder:
            card = PrayerCard(name)
            self.cards[name] = card
            cards_layout.addWidget(card)
        self.cards_layout = cards_layout
        layout.addLayout(cards_layout)

        self.footer = QLabel(installed_version())
        self.footer.setAlignment(Qt.AlignCenter)
        self.footer.setFont(QFont("DejaVu Sans", 9))
        self.footer.setStyleSheet(f"color: {FOOTER_COLOR};")
        layout.addWidget(self.footer)

        outer.addWidget(container, alignment=Qt.AlignHCenter)

    # -------------------------
    # Date handling
    # -------------------------
    def open_date_picker(self):
        dialog = DatePickerDialog(self.view_date, self)
        if dialog.exec_() == QDialog.Accepted and dialog.selected_date:
            self.view_date = dialog.selected_date
            # Only arm the fallback for a genuine detour - picking today from the
            # calendar leaves the view following the calendar as before.
            self.browsed_at = (None if self.view_date == date_cls.today()
                               else datetime.now())
            self.refresh()

    def go_today(self):
        self.view_date = date_cls.today()
        self.browsed_at = None
        self.refresh()

    # -------------------------
    # Rendering
    # -------------------------
    def refresh(self):
        now = datetime.now()
        today = now.date()

        # This page is left open for days at a time, so the date it is pinned to has to
        # follow the calendar over midnight. Only a view that was tracking today moves;
        # a date the user picked by hand stays where they put it.
        if self.view_date == self.last_today:
            self.view_date = today
        self.last_today = today

        if (self.browsed_at is not None
                and (now - self.browsed_at).total_seconds() >= BROWSE_RESET_MINUTES * 60):
            self.browsed_at = None
            self.view_date = today

        is_today = self.view_date == today

        self.footer.setText(installed_version())
        self.date_btn.setText(self.view_date.strftime("%Y-%m-%d"))
        self.today_btn.setVisible(not is_today)

        rows = daily_rows(self.view_date, now, is_today)
        if not rows:
            self.badge.hide()
            for name in dailyPrayerOrder:
                self.cards[name].apply_state("--:--", None)
            return

        current_color = None
        current_remaining = None
        for row in rows:
            color = None
            makrooh = False
            if is_today and row["start"] and row["end"] and row["start"] <= now < row["end"]:
                color, makrooh = period_state(row["name"], row["start"], row["end"], now)
                current_color = color
                current_remaining = int((row["end"] - now).total_seconds() // 60)
            text = row["time"].strftime("%H:%M") if row["time"] else "--:--"
            self.cards[row["name"]].apply_state(text, color, makrooh)

        # A card that just grew or shrank leaves the layout stale, which shows up as an
        # uneven gap beside the active row until something else forces a re-layout.
        self.cards_layout.activate()

        if current_color is None:
            self.badge.hide()
            return

        hours = current_remaining // 60
        minutes = current_remaining % 60
        self.badge.setText(f"{hours:02d}:{minutes:02d}")
        base = QColor(PERIOD_COLORS[current_color])
        self.badge.setStyleSheet(
            f"color: {PERIOD_TEXT[current_color]};"
            " background: qlineargradient(x1:0, y1:0, x2:1, y2:1,"
            f" stop:0 {base.lighter(112).name()}, stop:1 {base.darker(122).name()});"
            f" border: 2px solid {base.lighter(118).name()};"
            " border-radius: 20px; padding: 4px 14px;"
        )
        glow = QColor(base); glow.setAlpha(120)
        self.badge_glow.setColor(glow)
        self.badge.show()


