# PyQt5 UI
# -------------------------
class AdhanCounter(QWidget):
    def __init__(self):
        super().__init__()

        self.setWindowFlags(Qt.FramelessWindowHint)
        self.setWindowTitle("عداد الأذان")
        self.setWindowIcon(app_icon())
        self.setLayoutDirection(Qt.RightToLeft)

        # Countdown page
        self.counter_page = QWidget()
        self.counter_page.setObjectName("counterPage")
        self.counter_page.setAttribute(Qt.WA_StyledBackground, True)

        # Layout
        self.layout = QVBoxLayout()
        self.layout.setAlignment(Qt.AlignCenter)
        # Replaced by prayer_name_top_margin on the first update, which happens before
        # the window is shown.
        self.layout.setContentsMargins(COUNTDOWN_SIDE_MARGIN, 0,
                                       COUNTDOWN_SIDE_MARGIN, COUNTDOWN_BOTTOM_MARGIN)

        # Labels
        # Set per tick by update_countdown(); only ever holds the makrooh warning.
        self.title = QLabel("")
        self.prayerName = QLabel("")
        self.countdown = QLabel("--:--")

        self.title.setAlignment(Qt.AlignCenter)
        self.prayerName.setAlignment(Qt.AlignCenter)
        self.countdown.setAlignment(Qt.AlignCenter)

        # --------- COUNTDOWN CONFIG ---------
        self.countdown.setFont(fit_countdown_font(800, 480))
        self.countdown.setAttribute(Qt.WA_TranslucentBackground)
        self.countdown.setStyleSheet("background: transparent; color: white;")

        self.scene = scene = QGraphicsScene(self)
        self.proxy = QGraphicsProxyWidget()
        self.proxy.setWidget(self.countdown)

        # Set Initial Transform (Standard V1 Look)
        self.proxy.setTransform(QTransform().scale(1.0, COUNTDOWN_DIGITS_STRETCH_Y))

        self.view = view = QGraphicsView(scene)
        scene.addItem(self.proxy)
        view.setAlignment(Qt.AlignCenter)
        view.setStyleSheet("background: transparent; border: none;")
        view.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        view.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)


        self.layout.addWidget(view)

        scene.setBackgroundBrush(Qt.transparent)
        view.setBackgroundBrush(Qt.transparent)
        view.setAttribute(Qt.WA_TranslucentBackground)
        # ----------------------------------------------------------

        self.counter_page.setLayout(self.layout)

        # Sits over the page, spanning its full width so the text stays centred on the
        # page; fit_notice_font keeps it narrow enough to clear the window buttons.
        # Placed, not laid out - see COUNTDOWN_VIEW_TOP_RATIO.
        self.prayerName.setParent(self.counter_page)

        self.title.setParent(self.counter_page)
        self.title.setGeometry(0, COUNTDOWN_NOTICE_TOP, 800, COUNTDOWN_NOTICE_HEIGHT)
        self.title.raise_()

        # Fonts
        self.title.setFont(QFont(COUNTDOWN_NAME_FONT, 30))
        self.prayerName.setFont(QFont(COUNTDOWN_NAME_FONT, 70))

        # Pages
        self.daily_page = DailyPrayersPage()

        self.stack = QStackedWidget()
        self.stack.addWidget(self.counter_page)
        self.stack.addWidget(self.daily_page)

        root_layout = QVBoxLayout(self)
        root_layout.setContentsMargins(0, 0, 0, 0)
        root_layout.addWidget(self.stack)

        # Exit button
        self.exit_btn = QPushButton("✖", self)
        self.exit_btn.setGeometry(*window_button_box(0, EXIT_ICON_Y))
        self.exit_btn.clicked.connect(QApplication.instance().quit)
        self.exit_btn.show()

        # Fullscreen toggle
        self.fullscreen_btn = QPushButton("⛶", self)
        self.fullscreen_btn.setGeometry(*window_button_box(1, FULLSCREEN_ICON_Y))
        self.fullscreen_btn.clicked.connect(self.toggle_fullscreen)
        self.fullscreen_btn.show()

        # Switch between the countdown and the daily prayer table
        self.view_btn = QPushButton("☰", self)
        self.view_btn.setGeometry(*window_button_box(2, VIEW_ICON_Y_COUNTER))
        self.view_btn.clicked.connect(self.toggle_view)
        self.view_btn.show()

        # Silences every scheduled athan until it is tapped again. WINDOW_BUTTON_PITCH
        # is 48 rather than the original 60 because a fourth button at the old pitch
        # reached x=240, and the centred countdown title starts at x=225.
        self.mute_btn = QPushButton(SPEAKER_ON, self)
        self.mute_btn.setGeometry(*window_button_box(3, MUTE_ICON_Y))
        self.mute_btn.clicked.connect(self.toggle_mute)
        self.mute_btn.show()
        # Counts down to the next reading of the device; zero forces one on the next
        # tick. None means the device has not been read yet, or cannot be read at all.
        self.audio_poll_due = 0
        self.audio_sink_muted = None

        # A launch is a clean slate. Whatever left the device silent - a mute that
        # outlived the app, a crash part way through one - is lifted here, along with
        # the flag that goes with it, so the app can never come up unable to be heard
        # with nothing on screen to say why. The flag goes too: leaving it would keep
        # the scheduler skipping athans while the button reported sound as on.
        self.muted = False
        self.clear_mute_flag()
        # A kiosk starts this app as it starts the audio session, so the device may not
        # answer yet. Keep asking rather than coming up silent on a lost race.
        self.force_unmute_pending = not self.set_audio_muted(False)

        btn_style = """
        QPushButton {
            color: black !important;
            background: transparent;
            border: none;
            font-size: %dpx;
        }
        """ % WINDOW_BUTTON_FONT_PX
        self.btn_style = btn_style
        self.page_button_color = "black"
        self.paint_window_buttons("black")

        for button in (self.exit_btn, self.fullscreen_btn, self.view_btn,
                       self.mute_btn):
            button.raise_()
            # Subpixel antialiasing tints thin strokes orange on one edge and blue on
            # the other. On the speaker's sound waves that is strong enough to read as
            # colour, which would compete with the red that means muted.
            icon_font = button.font()
            icon_font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
            button.setFont(icon_font)

        # Timer
        self.timer = QTimer()
        self.timer.timeout.connect(self.tick)
        self.timer.start(1000)

        # Every font is now fitted to the window, so the window has to know its size
        # before the first fit. X11 grants fullscreen asynchronously - ask for it and
        # width() still reads the pre-fullscreen default for a frame - so the geometry
        # is taken from the screen up front and the first paint is already right.
        screen = QApplication.primaryScreen()
        if screen is not None:
            self.resize(screen.geometry().size())

        self._ready = True
        self.showFullScreen()
        self.update_countdown()

    # -------------------------
    # View switching
    # -------------------------
    def paint_window_buttons(self, color):
        style = self.btn_style.replace("color: black !important;", f"color: {color};")
        for button in (self.exit_btn, self.fullscreen_btn, self.view_btn):
            button.setStyleSheet(style)
        self.page_button_color = color
        self.paint_mute_button()

    # -------------------------
    # Mute handling
    # -------------------------
    def paint_mute_button(self):
        """Sized on its own because the speaker sits lighter than the other three icons
        at the size they share."""
        color = MUTED_COLOR if self.muted else self.page_button_color
        self.mute_btn.setText(SPEAKER_OFF if self.muted else SPEAKER_ON)
        size = MUTE_ICON_SIZE_MUTED if self.muted else MUTE_ICON_SIZE
        self.mute_btn.setStyleSheet(
            "QPushButton { background: transparent; border: none;"
            f" font-size: {size}px; font-weight: bold; color: {color}; }}")
        icon_font = QFont(SYMBOL_FONT)
        icon_font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
        self.mute_btn.setFont(icon_font)

    def toggle_mute(self):
        """The flag governs athans still to come; the device governs the one playing now.

        Both are set together so the button means one thing - sound off - rather than
        two that can disagree."""
        # A tap settles it either way, so a launch-time unmute still owed is dropped.
        self.force_unmute_pending = False
        if self.muted:
            self.clear_mute_flag()
            self.muted = False
            self.set_audio_muted(False)
        else:
            deadline = datetime.now() + timedelta(minutes=MUTE_DURATION_MINUTES)
            os.makedirs(os.path.dirname(MUTE_FLAG_FILE), exist_ok=True)
            with open(MUTE_FLAG_FILE, "w") as flag:
                flag.write(f"{int(deadline.timestamp())}\n")
            self.muted = True
            # Only if the device cannot be silenced is the player killed instead. That
            # silences it just as fast but cannot be undone, so it is the last resort.
            if not self.set_audio_muted(True):
                self.stop_current_audio()
        self.paint_mute_button()

    def set_audio_muted(self, muted):
        """Silence or restore the device, and remember how it was left so the button is
        right at once rather than at the next reading."""
        done = audio_set_mute(muted)
        self.audio_sink_muted = muted if done else None
        self.audio_poll_due = AUDIO_STATE_POLL_SECONDS
        return done

    def clear_mute_flag(self):
        try:
            os.remove(MUTE_FLAG_FILE)
        except FileNotFoundError:
            pass
        except OSError:
            pass

    def stop_current_audio(self):
        """Muting part way through an athan should cut what is already playing. The
        player script kills its own vlc child from its EXIT trap, so signalling the
        script is enough - and it runs as this same user, so no sudo is involved."""
        try:
            subprocess.run(["pkill", "-TERM", "-f", PLAYER_SCRIPT_FILE], check=False)
        except OSError:
            pass

    def sync_mute_state(self):
        """The flag can also be cleared from a shell, so follow the file, not just taps.
        This is where a lapsed mute is tidied away: the readers already ignore an expired
        deadline, but removing the file keeps them from having to parse it every event.

        A lapsed mute also gives the device its sound back. Without that the speaker
        would stay silent with nothing left on screen or on disk to say why."""
        if self.force_unmute_pending:
            self.force_unmute_pending = not self.set_audio_muted(False)

        muted = is_muted()
        if not muted and os.path.exists(MUTE_FLAG_FILE):
            self.clear_mute_flag()
            self.set_audio_muted(False)

        # The device is read on a slower beat than the tick, so the last reading is kept
        # rather than re-derived: recomputing from the flag in between would flip the
        # button back and forth between polls.
        self.audio_poll_due -= 1
        if self.audio_poll_due <= 0:
            self.audio_poll_due = AUDIO_STATE_POLL_SECONDS
            self.audio_sink_muted = audio_is_muted()

        # The button reports the speaker, not the intent: whatever silenced the device,
        # showing sound as on while nothing can be heard would be the one useless state.
        # None means there is no device to ask - on that fallback path the player was
        # killed rather than silenced, so the flag is all there is to go on.
        if self.audio_sink_muted is not None:
            muted = self.audio_sink_muted

        if muted != self.muted:
            self.muted = muted
            self.paint_mute_button()

    def toggle_view(self):
        if self.stack.currentWidget() is self.counter_page:
            # Always open the table on today, whatever date was last browsed
            self.daily_page.go_today()
            self.stack.setCurrentWidget(self.daily_page)
            self.view_btn.setText("◷")
            self.view_btn.setGeometry(*window_button_box(2, VIEW_ICON_Y_DAILY))
            self.paint_window_buttons(PAGE_TEXT)
        else:
            self.stack.setCurrentWidget(self.counter_page)
            self.view_btn.setText("☰")
            self.view_btn.setGeometry(*window_button_box(2, VIEW_ICON_Y_COUNTER))
            self.paint_window_buttons("black")
            self.update_countdown()

    def tick(self):
        self.sync_mute_state()
        # Nothing downstream caches the times - daily_times reads prayersByDate on
        # every call - so refreshing the dict is the whole job. The refresh below
        # then redraws whichever page is showing with the new times.
        if prayer_times_changed():
            load_prayer_times()
        if self.stack.currentWidget() is self.daily_page:
            self.daily_page.refresh()
        else:
            self.update_countdown()

    # -------------------------
    # Countdown logic
    # -------------------------
    def frame_digits(self, proxy_pos_y, proxy_scale_y):
        """Show the view the digits, not the line box around them.

        A font's line box can stand well clear of the glyphs inside it - room for accents
        and descenders these digits never use. Left alone the view centres that empty box,
        which drops the digits low and crops them at its edge. Framing the painted band
        instead centres the digits themselves, whatever the font."""
        # A proxy keeps whatever size it was given; it does not grow when the widget's
        # font does. Left alone the label stays at its construction width and the digits
        # are clipped by their own label, off centre inside a scene rect sized for the
        # text they were meant to have.
        self.proxy.resize(QSizeF(self.countdown.sizeHint()))

        metrics = QFontMetrics(self.countdown.font())
        ink = metrics.tightBoundingRect("00:00")
        top_in_label = metrics.ascent() + ink.top()
        self.scene.setSceneRect(
            0,
            proxy_pos_y + top_in_label * proxy_scale_y,
            self.countdown.sizeHint().width(),
            ink.height() * proxy_scale_y,
        )

    def update_countdown(self):
        now = datetime.now()
        prev_p, next_p, prev_t, next_t = get_prev_next_prayer(now)

        if not next_t or not prev_t:
            self.countdown.setText("--:--")
            self.paint_counter_page("#808080")
            return

        # =========================================================
        # 1. ESTABLISH BASELINE (Exact Version 1 Settings)
        # =========================================================
        # We reset these every second so normal cases look normal.

        # Text
        # The small line is now only ever the makrooh warning; the prayer name below
        # says what is being counted down to.
        title_text = ""

        # Fonts are chosen at apply-time from the text that ends up being shown.

        # Positioning & Scale
        proxy_pos_y = COUNTDOWN_SHIFT_Y
        proxy_scale_y = COUNTDOWN_DIGITS_STRETCH_Y

        # Background
        bg = COUNTDOWN_BG_DEFAULT

        # =========================================================
        # 2. CALCULATE TIME
        # =========================================================
        remaining = int((next_t - now).total_seconds())
        hours = remaining // 3600
        minutes = (remaining % 3600) // 60

        self.countdown.setText(f"{hours:02d}:{minutes:02d}")

        # The name is the period now in force, not the athan being counted down to - the
        # same sense the الشروق and الضحى branches below already use.
        label = prayer_display_name(prev_p)

        since_prev = (now - prev_t).total_seconds()

        # =========================================================
        # 3. CONDITIONAL LOGIC (Only override if needed)
        # =========================================================

        window = duha_window(now)

        # The الشروق -> الظهر stretch belongs to الضحى: makrooh until الضحى opens, then
        # an ordinary period with its own green start and red (zawal) finish.
        if window:
            duha_start, dhuhr_dt = window
            edge = timedelta(minutes=PERIOD_EDGE_MINUTES)

            if now < duha_start:
                # Still الشروق's own window - name it as such; الضحى has not opened yet.
                label = prayer_display_name("الشروق")
                bg = COUNTDOWN_BG_MAKROOH
                title_text = "(الوقت مكروه لصلاة الضحى)"
                target = duha_start
            else:
                label = prayer_display_name("الضحى")
                target = dhuhr_dt
                if now < duha_start + edge:
                    bg = COUNTDOWN_BG_GREEN
                elif dhuhr_dt - now <= edge:
                    # Zawal is makrooh, not just "Dhuhr is close" - so it takes the
                    # makrooh orange, the same as the sunrise window above, rather
                    # than the red that only means the next athan is near.
                    bg = COUNTDOWN_BG_MAKROOH
                    title_text = "(الوقت مكروه لصلاة الضحى)"

            remaining = max(0, int((target - now).total_seconds()))
            hours = remaining // 3600
            minutes = (remaining % 3600) // 60
            self.countdown.setText(f"{hours:02d}:{minutes:02d}")

        # A. Green: Post-Athan (0 to 20 mins) - Standard Layout
        elif 0 <= since_prev <= 1200 and prev_p != "الشروق":
            bg = COUNTDOWN_BG_GREEN

        # B. Red: Pre-Athan Warning (Last 20 mins)
        elif 0 < remaining <= 1200:
            bg = COUNTDOWN_BG_RED

        # =========================================================
        # 4. APPLY SETTINGS
        # =========================================================

        # Apply Fonts
        width = self.width() or 800
        height = self.height() or 480
        name_font = fit_prayer_font(width, height)
        self.prayerName.setFont(name_font)

        top_margin = prayer_name_top_margin(name_font, height)
        self.title.setText(title_text)
        self.prayerName.setText(label)
        self.prayerName.setGeometry(
            COUNTDOWN_SIDE_MARGIN, top_margin,
            max(0, width - 2 * COUNTDOWN_SIDE_MARGIN),
            QFontMetrics(name_font).height())
        self.prayerName.raise_()
        # An empty label still claims a line box, which would leave a gap where the old
        # static title used to sit.
        self.title.setVisible(bool(title_text))
        self.title.setGeometry(0, COUNTDOWN_NOTICE_TOP, width, COUNTDOWN_NOTICE_HEIGHT)
        # One cap for every state: the notice is out of the layout, so it no longer
        # competes with the name for height and the name need not shrink for it.
        if title_text:
            self.title.setFont(fit_notice_font(title_text, width))
        self.countdown.setFont(fit_countdown_font(width, height))
        self.layout.setContentsMargins(
            COUNTDOWN_SIDE_MARGIN, round(height * COUNTDOWN_VIEW_TOP_RATIO),
            COUNTDOWN_SIDE_MARGIN, COUNTDOWN_BOTTOM_MARGIN)

        # Apply Graphics Transform & Position
        self.proxy.setPos(0, proxy_pos_y)
        self.proxy.setTransform(QTransform().scale(1.0, proxy_scale_y))
        self.frame_digits(proxy_pos_y, proxy_scale_y)

        # Apply Colors
        self.paint_counter_page(bg)

    def paint_counter_page(self, bg):
        """Scoped to the countdown page so the daily table keeps its own light theme."""
        self.counter_page.setStyleSheet(
            f"#counterPage {{ background: {bg}; }}"
            "#counterPage QLabel { color: white; }"
        )

    # -------------------------
    # Fullscreen handling
    # -------------------------
    def resizeEvent(self, event):
        """Fonts are fitted to the window, and X11 grants fullscreen asynchronously - the
        first update runs while the window is still at its pre-fullscreen size, so every
        font comes out small and stays that way until the next tick a second later.
        Re-fitting here puts the right sizes up on the frame the window actually reaches
        its size, and keeps them right across the fullscreen/maximised toggle."""
        super().resizeEvent(event)
        if not getattr(self, "_ready", False) or getattr(self, "_refitting", False):
            return
        self._refitting = True
        try:
            self.update_countdown()
        finally:
            self._refitting = False

    def toggle_fullscreen(self):
        if self.isFullScreen():
            self.showMaximized()
        else:
            self.showFullScreen()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_F11:
            self.toggle_fullscreen()
        elif event.key() == Qt.Key_Escape and self.isFullScreen():
            self.showMaximized()

# -------------------------
# Run app
# -------------------------
if __name__ == "__main__":
    app = QApplication(sys.argv)
    # The panel's task list is handed a window's app_id and nothing else, and for an
    # XWayland window that app_id is the WM_CLASS Qt derives from argv[0] - "main.py",
    # which is also what the Settings app reports and which matches no desktop entry.
    # With no entry to resolve, the panel falls back to the process behind the window,
    # python3, and draws the Python logo. Nothing here matches this app by class - the
    # updater and the health check both go by the command line - so naming it after its
    # own desktop entry costs nothing and gives the panel something to find.
    app.setApplicationName("prayer_times_gui")
    app.setDesktopFileName("prayer_times_gui")
    window = AdhanCounter()
    window.show()
    sys.exit(app.exec_())
